function asArray(v:any):string[]{if(Array.isArray(v))return v.map(String);if(typeof v==='string'){try{const j=JSON.parse(v);return Array.isArray(j)?j.map(String):[];}catch{return [];}}return [];}
function asObject(v:any):any{if(v&&typeof v==='object')return v;if(typeof v==='string'){try{return JSON.parse(v);}catch{return {};}}return {};}
function joinNames(xs:string[]){if(xs.length<=1)return xs[0]??'';if(xs.length===2)return `${xs[0]} and ${xs[1]}`;return `${xs.slice(0,-1).join(', ')}, and ${xs[xs.length-1]}`;}
function discordTs(v:any){const n=Math.floor(new Date(v).getTime()/1000);return Number.isFinite(n)?`<t:${n}:F>`:String(v??'');}
async function roleNames(client:Client,ids:string[]){const g=client.guilds.cache.get(guildId);return ids.map(id=>g?.roles.cache.get(id)?.name??id);}
function userMention(id:string|null|undefined,fallback:string){return id&&/^\d{15,22}$/.test(id)?`<@${id}>`:fallback;}
function roleMention(id:string,fallback:string){return /^\d{15,22}$/.test(id)?`<@&${id}>`:fallback;}
function channelMention(id:string|null|undefined,fallback:string){return id&&/^\d{15,22}$/.test(id)?`<#${id}>`:fallback;}
