function stateName(row:any){const before=asObject(row.before_state),after=asObject(row.after_state),meta=asObject(row.metadata);return String(after.name??before.name??after.topic??before.topic??meta.name??'').trim()||null;}
function stripAudit(action:string){return action.startsWith('audit.')?action.slice(6):action;}
function actionHuman(action:string){
  const a=stripAudit(action);
  const exact:Record<string,string>={
    'member.joined':'joined the server','member.left':'left the server','member.nickname.changed':'had their nickname changed','member.kick':'was kicked','member.ban.add':'was banned','member.ban.remove':'was unbanned','member.timeout.changed':'had their timeout changed',
    'role.created':'created the role','role.updated':'changed the role','role.deleted':'deleted the role','channel.created':'created the channel','channel.updated':'changed the channel','channel.deleted':'deleted the channel','channel.overwrite.create':'created a channel permission overwrite','channel.overwrite.update':'changed a channel permission overwrite','channel.overwrite.delete':'deleted a channel permission overwrite',
    'thread.created':'created the thread','thread.updated':'changed the thread','thread.deleted':'deleted the thread','voice.channel.joined':'joined voice','voice.channel.left':'left voice','member.move':'moved the member in voice','member.disconnect':'disconnected the member from voice',
    'invite.created':'created an invite','invite.deleted':'deleted an invite','invite.create':'created an invite','invite.delete':'deleted an invite','message.created':'sent a message','message.edited':'edited a message','message.deleted':'deleted a message','message.bulk_deleted':'bulk-deleted messages','message.delete':'deleted a message','message.bulk.delete':'bulk-deleted messages','message.pin':'pinned a message','message.unpin':'unpinned a message',
    'reaction.added':'added a reaction','reaction.removed':'removed a reaction','reaction.all_removed':'cleared all reactions','webhook.create':'created a webhook','webhook.update':'changed a webhook','webhook.delete':'deleted a webhook','webhook.collection.updated':'changed webhooks in the channel',
    'emoji.created':'created an emoji','emoji.updated':'changed an emoji','emoji.deleted':'deleted an emoji','emoji.create':'created an emoji','emoji.update':'changed an emoji','emoji.delete':'deleted an emoji','sticker.created':'created a sticker','sticker.updated':'changed a sticker','sticker.deleted':'deleted a sticker','sticker.create':'created a sticker','sticker.update':'changed a sticker','sticker.delete':'deleted a sticker',
    'scheduled_event.created':'created a scheduled event','scheduled_event.updated':'changed a scheduled event','scheduled_event.deleted':'deleted a scheduled event','guild.updated':'changed server settings','guild.update':'changed server settings','guild.integrations.updated':'changed server integrations',
    'automod.rule.created':'created an AutoMod rule','automod.rule.updated':'changed an AutoMod rule','automod.rule.deleted':'deleted an AutoMod rule','automod.action.executed':'triggered an AutoMod action'
  };
  if(exact[a])return exact[a];
  return a.replaceAll('.',' ').replace(/\b(create|created)\b/g,'created').replace(/\b(update|updated)\b/g,'changed').replace(/\b(delete|deleted)\b/g,'deleted');
}
async function targetDisplay(client:Client,row:any,member:any,channel:any,role:any,named:any){
  const tid=String(row.target_id??'');
  if(member&&tid===String(member.id))return {plain:member.displayName,discord:userMention(member.id,member.displayName),userId:String(member.id)};
  if(channel&&(tid===String(channel.id)||String(row.channel_id??'')===String(channel.id)))return {plain:`#${channel.name}`,discord:channelMention(channel.id,`#${channel.name}`)};
  if(role&&tid===String(role.id))return {plain:`@${role.name}`,discord:roleMention(role.id,`@${role.name}`),roleId:String(role.id)};
  if(named&&tid===String(named.id))return {plain:named.name,discord:named.name};
  const g=client.guilds.cache.get(guildId);if(tid){const gm=g?.members.cache.get(tid);if(gm)return {plain:gm.displayName,discord:userMention(tid,gm.displayName),userId:tid};const gr=g?.roles.cache.get(tid);if(gr)return {plain:`@${gr.name}`,discord:roleMention(tid,`@${gr.name}`),roleId:tid};const gc=g?.channels.cache.get(tid) as any;if(gc?.name)return {plain:`#${gc.name}`,discord:channelMention(tid,`#${gc.name}`)};}
  const n=stateName(row);if(n)return {plain:n,discord:n};return {plain:tid||'the target',discord:tid||'the target'};
}
