    const memberTarget=['member.joined','member.left','member.nickname','member.kick','member.ban','member.unban','member.timeout','voice.disconnect','voice.move','voice.mute','voice.deafen'].includes(kind);if(member&&memberTarget){params.push(member.id);where.push(`target_id=$${params.length}`);}
    if(member&&['message.created','message.edited'].includes(kind)){params.push(member.id);where.push(`(actor_id=$${params.length} OR metadata->>'authorId'=$${params.length})`);}
    if(member&&['message.deleted','message.bulk_deleted'].includes(kind)){const asActor=/\b(messages?|posts?)\s+(?:deleted|removed)\s+by\b|\bhow many\b[^?]{0,80}\b(?:did|has|have)\b/i.test(q);params.push(member.id);where.push(asActor?`(initiator_id=$${params.length} OR actor_id=$${params.length})`:`(metadata->>'authorId'=$${params.length} OR target_id=$${params.length})`);}
