    if(channel&&(['channel.created','channel.deleted','channel.changed','thread.created','thread.deleted','thread.changed','invite.created','invite.deleted','message.deleted','message.edited','message.created','message.bulk_deleted','message.pinned','message.unpinned','reaction.added','reaction.removed','reaction.cleared','webhook.created','webhook.changed','webhook.deleted','voice.join','voice.leave','voice.disconnect','voice.move','voice.mute','voice.deafen'].includes(kind))){params.push(channel.id);where.push(`(channel_id=$${params.length} OR target_id=$${params.length})`);}
    if(named&&['emoji.created','emoji.changed','emoji.deleted','sticker.created','sticker.changed','sticker.deleted','scheduled_event.created','scheduled_event.changed','scheduled_event.deleted','scheduled_event.user_added','scheduled_event.user_removed','automod.rule.created','automod.rule.changed','automod.rule.deleted'].includes(kind)){params.push(named.id);where.push(`target_id=$${params.length}`);}
