async function answerGenericKind(client:Client,kind:QuestionKind,q:string,member:any,channel:any,role:any,named:any):Promise<SentinelAnswer>{await freshenAudit(client);const result=await queryKindEvents(kind,q,member,channel,role,named);const label=kind.replaceAll('.',' ');if(result.mode==='count')return {text:`I found ${result.count} matching ${label} event${result.count===1?'':'s'}${result.range.label?` in ${result.range.label}`:''}.`,confidence:'confirmed',kind};if(!result.rows.length)return {text:`I don't have a matching recorded ${label} event${result.range.label?` in ${result.range.label}`:''}.`,confidence:'unknown',kind};if(result.mode==='history'||kind.startsWith('activity.')){const lines:string[]=[];const userIds=new Set<string>(),roleIdsOut=new Set<string>();for(const row of result.rows){const n=await eventNarrative(client,row,member,channel,role,named);lines.push(`• ${n.plain}`);n.userIds.forEach(x=>userIds.add(x));n.roleIds.forEach(x=>roleIdsOut.add(x));}return {text:lines.join('\n'),eventId:String(result.rows[0].id),confidence:'confirmed',kind,related:result.rows,userMentionIds:[...userIds],roleMentionIds:[...roleIdsOut]};}const row=result.rows[0],n=await eventNarrative(client,row,member,channel,role,named);return {text:n.plain,discordText:n.discord,eventId:String(row.id),confidence:(row.initiator_id??row.actor_id)?'confirmed':row.attribution_confidence==='causal'?'causal':'probable',kind,userMentionIds:n.userIds,roleMentionIds:n.roleIds};}
