  if(kind==='member.ban.current'){const ban=await g.bans.fetch(id).catch(()=>null);return {text:`${plain} is ${ban?'currently banned':'not currently banned'} from the server.`,discordText:`${mention} is ${ban?'currently banned':'not currently banned'} from the server.`,confidence:'confirmed',kind,userMentionIds:[id]};}
