  if(kind==='member.nickname.current'){const nick=m.nickname;return {text:nick?`${m.user.username}'s current server nickname is ${nick}.`:`${m.displayName} does not currently have a server nickname.`,discordText:nick?`${mention}'s current server nickname is **${nick}**.`:`${mention} does not currently have a server nickname.`,confidence:'confirmed',kind,userMentionIds:[id]};}
  if(kind==='member.timeout.current'){const until=m.communicationDisabledUntil;const active=Boolean(until&&until.getTime()>Date.now());return {text:active?`${m.displayName} is currently timed out until ${until.toISOString()}.`:`${m.displayName} is not currently timed out.`,discordText:active?`${mention} is currently timed out until ${discordTs(until)}.`:`${mention} is not currently timed out.`,confidence:'confirmed',kind,userMentionIds:[id]};}
