async function answerMemberRoleHistory(client:Client,kind:QuestionKind,q:string,member:any,role:any):Promise<SentinelAnswer>{
  await freshenAudit(client);const mode=questionMode(q),range=questionTimeRange(q);
  const result=await queryRoleHistory({guildId,memberId:String(member.id),roleId:role?.id,direction:kind==='role.gained'?'added':kind==='role.lost'?'removed':undefined,range,limit:mode==='count'?0:50});
  if(mode==='count')return {text:`I found ${result.count} recorded ${kind==='role.gained'?'role assignment':kind==='role.lost'?'role removal':'role-change'} events for ${member.displayName}${range.label?` in ${range.label}`:''}.`,confidence:'confirmed',kind};
  const rows=result.rows;if(!rows.length)return {text:`I don't have a matching recorded role change for ${member.displayName}${range.label?` in ${range.label}`:''}.`,confidence:'unknown',kind};
  const changes=[] as {row:any,added:string[],removed:string[],actorId:string|null,actor:string|null}[];for(const row of rows){const meta=asObject(row.metadata),added=asArray(meta.added),removed=asArray(meta.removed);const actorId=row.initiator_id??row.actor_id??null,actor=await displayActor(client,actorId);changes.push({row,added,removed,actorId,actor});}
  const render=async(c:typeof changes[number])=>{const addNames=await roleNames(client,c.added),removeNames=await roleNames(client,c.removed);const parts=[] as string[];if(addNames.length)parts.push(`added ${joinNames(addNames)}`);if(removeNames.length)parts.push(`removed ${joinNames(removeNames)}`);return `${c.actor??'An unknown actor'} ${parts.join(' and ')||'changed roles'} for ${member.displayName} on ${discordTs(c.row.occurred_at)}.`;};
  if(mode==='history'||kind==='member.roles.changed'||(!role&&(kind==='role.gained'||kind==='role.lost'))){const lines=[] as string[];for(const c of changes.slice(0,10))lines.push(`• ${await render(c)}`);return {text:lines.join('\n')+(result.count>10?`\n• +${result.count-10} more recorded role changes`:''),eventId:String(changes[0].row.id),confidence:'confirmed',kind,related:rows};}
  const c=changes[0];return {text:await render(c),eventId:String(c.row.id),confidence:c.actor?'confirmed':'probable',kind,userMentionIds:[String(member.id),...(c.actorId?[String(c.actorId)]:[])]};
}
export async function sentinelAnswer(client:Client,q:string):Promise<SentinelAnswer>{
  let kind=questionKind(q);let member=await resolveMember(client,q),channel=await resolveChannel(client,q),role=await resolveRole(client,q);let aiAccessIntent:AccessQuestionIntent|null=null;
  if(!member)member=await historicalMember(q);if(!channel)channel=await historicalChannel(q);if(!role)role=await historicalRole(q);
  let missing=missingEntity(kind,member,channel,role);
  if((kind==='unknown'||missing)&&openAIEnabled('OPENAI_SENTINEL_ENABLED')){const ai=await aiInterpretSentinelQuestion(client,q);if(ai){kind=ai.kind;const g=client.guilds.cache.get(guildId);if(ai.memberId)member=g?.members.cache.get(ai.memberId)??await g?.members.fetch(ai.memberId).catch(()=>null)??member;if(ai.channelId)channel=g?.channels.cache.get(ai.channelId)??channel;if(ai.roleId)role=g?.roles.cache.get(ai.roleId)??role;aiAccessIntent=ai.accessIntent??null;missing=missingEntity(kind,member,channel,role);}}
  if(missing)return missing;
  if(kind==='access')return answerAccessQuestion(client,q,member,channel,aiAccessIntent);
  if(['access.members','access.roles','access.channels.member','access.channels.role','access.role.current','access.permissions'].includes(kind))return answerAccessScope(client,kind,q,member,channel,role);
  if(kind==='member.roles.current')return answerCurrentRoles(member);
  if(kind==='role.members')return answerRoleMembers(client,role);
  if(kind==='voice.current')return answerCurrentVoice(member);
  if(kind==='voice.members.current')return answerVoiceMembers(client,channel);
  if(kind==='member.bans.current'||kind==='member.timeouts.current')return answerCurrentModerationLists(client,kind);
  if(kind==='invite.current')return answerCurrentInvites(client,q);
  if(['member.nickname.current','member.ban.current','member.timeout.current','voice.mute.current','voice.deafen.current'].includes(kind))return answerCurrentMemberState(client,kind,member);
  if(kind==='role.current')return answerCurrentRole(client,member,role,q);
  if(kind==='member.roles.changed')return answerMemberRoleHistory(client,kind,q,member,role);
  if((kind==='role.gained'||kind==='role.lost')&&role)return answerMemberRoleHistory(client,kind,q,member,role);
  if((kind==='role.gained'||kind==='role.lost')&&!role)return answerMemberRoleHistory(client,kind,q,member,role);
  if((kind==='voice.disconnect'||kind==='voice.move')&&member)return answerVoiceQuestion(client,kind,member,channel);
  if(kind==='invite.used')return answerInviteQuestion(client,member);
  if(member&&['member.kick','member.ban','member.unban','member.timeout','voice.mute','voice.deafen'].includes(kind))return answerModerationQuestion(client,kind,member);
  const namedCategories=kind.startsWith('emoji.')?['emoji']:kind.startsWith('sticker.')?['sticker']:kind.startsWith('scheduled_event.')?['scheduled_event']:kind.startsWith('automod.rule.')?['automod']:[];const named=namedCategories.length?await historicalNamedTarget(q,namedCategories):null;
  if(kind==='unknown'){
    const params:any[]=[guildId],where=['guild_id=$1'];if(member){params.push(member.id);where.push(`(target_id=$${params.length} OR initiator_id=$${params.length} OR actor_id=$${params.length})`);}if(channel){params.push(channel.id);where.push(`(channel_id=$${params.length} OR target_id=$${params.length})`);}if(role){params.push(role.id);where.push(`(target_id=$${params.length} OR metadata::text LIKE '%' || $${params.length} || '%')`);}appendTimeRange(where,params,questionTimeRange(q));const terms=questionTokens(q).slice(0,8).join(' & ');if(terms){params.push(terms);where.push(`to_tsvector('simple',action||' '||category||' '||source||' '||metadata::text) @@ plainto_tsquery('simple',$${params.length})`);}const rows=await many<any>(`SELECT * FROM sentinel_events WHERE ${where.join(' AND ')} ORDER BY occurred_at DESC LIMIT 5`,params);if(rows.length===1){const n=await eventNarrative(client,rows[0],member,channel,role,named);return {text:n.plain,discordText:n.discord,eventId:String(rows[0].id),confidence:(rows[0].initiator_id??rows[0].actor_id)?'confirmed':'probable',kind:'event.match',userMentionIds:n.userIds,roleMentionIds:n.roleIds};}if(rows.length>1&&questionMode(q)==='history'){const lines:string[]=[];for(const row of rows){const n=await eventNarrative(client,row,member,channel,role,named);lines.push(`• ${n.plain}`);}return {text:lines.join('\n'),eventId:String(rows[0].id),confidence:'confirmed',kind:'event.history',related:rows};}return {text:`I couldn't pin that down from the server history I have. Try adding the member, channel or role, the action, or a time window.`,confidence:'unknown',kind:'unknown',related:rows};
  }
  return answerGenericKind(client,kind,q,member,channel,role,named);
}

function passiveQuestionCandidate(text:string){const q=text.trim();if(q.length<12||q.length>1800)return false;if(!(/[?]/.test(q)||/\b(who|why|what|when|where|how|did|does|can|could|is|was|were|show|list)\b/i.test(q)))return false;return /\b(access|see|view|visible|role|permission|channel|chat|thread|voice|vc|disconnect|move|moved|invite|invited|join|joined|left|leave|deleted?|removed?|granted?|assigned|changed|modified|created?|renamed|ban|banned|unban|kick|kicked|timeout|muted|deafened|nickname|message|post|pin|pinned|reaction|reacted|webhook|emoji|emote|sticker|scheduled event|server event|automod|integration|server settings|guild|history|timeline|happened|currently|right now|who can|which channels|what permissions|active invites|timed out|who has)\b/i.test(q);}
function sentinelTitle(kind:string){if(kind.startsWith('access.channels'))return 'Channel access';if(kind==='access.permissions')return 'Effective permissions';if(kind.startsWith('access.'))return 'Access check';if(kind.startsWith('member.roles'))return 'Role history';if(kind.startsWith('voice.'))return 'Voice activity';if(kind.startsWith('invite.'))return 'Invite activity';if(kind.startsWith('member.'))return 'Member activity';return 'Sentinel answer';}
function friendlySentinelText(text:string){return String(text??'').replace(/ is currently denied \*\*View Channel\*\* on /g,' does not currently have **View Channel** in ').replace(/ denies \*\*View Channel\*\* to @everyone/g,' has **View Channel** turned off for @everyone').replace(/ cannot currently see /g," does not currently have access to ").replace(/ can no longer see /g,' no longer has access to ');}
function sentinelComponents(answer:SentinelAnswer,question?:string){
  const accent=answer.confidence==='unknown'?0x6B7280:answer.presentation?.status==='warning'?0xB7791F:answer.presentation?.status==='good'?0x3D8B5A:0xD6A83A;const body:any[]=[];body.push({type:10,content:`### ${answer.presentation?.title??sentinelTitle(answer.kind)}`});if(question)body.push({type:10,content:`-# ${question.slice(0,300)}`});const summary=friendlySentinelText(answer.presentation?.summary??answer.discordText??answer.text);body.push({type:10,content:summary.slice(0,3900)});let rendered=0;for(const section of answer.presentation?.sections??[]){if(rendered>=10)break;const items=section.items??[];if(!items.length)continue;body.push({type:14,divider:true,spacing:1});const pageSize=18;for(let i=0;i<items.length&&rendered<10;i+=pageSize){const page=items.slice(i,i+pageSize);const heading=i===0?`**${section.title}**\n`:'';body.push({type:10,content:(heading+page.map(x=>`• ${friendlySentinelText(x)}`).join('\n')).slice(0,3900)});rendered++;}}
  if(answer.confidence==='unknown')body.push({type:10,content:`-# I couldn't confirm every part of this answer from the server history currently available.`});const actions=[] as any[];if(answer.eventId)actions.push({type:2,style:5,label:'View event details',url:eventLink(answer.eventId)});actions.push({type:2,style:5,label:'Open Sentinel',url:`${dashboard}/dashboard/sentinel`});if(actions.length)body.push({type:1,components:actions.slice(0,5)});return [{type:17,accent_color:accent,components:body}] as any;}

async function maybePassiveSentinelReply(client:Client,message:any){
  if(await conversationOwner(message)!=='sentinel')return;
  const st=await archiveSettings();if(!st.passiveQaEnabled||!st.passiveQaChannelId||message.channelId!==st.passiveQaChannelId||!passiveQuestionCandidate(String(message.content??'')))return;
  const key=String(message.channelId),last=passiveCooldown.get(key)??0;if(Date.now()-last<2500)return;passiveCooldown.set(key,Date.now());
  const wrapped=await sentinelConversationAnswer(client,String(message.content??''),String(message.author?.id??'anonymous'),`sentinel:discord:${message.channelId}`);const answer=wrapped.answer;if(!['confirmed','causal'].includes(answer.confidence))return;
  passiveCooldown.set(key,Date.now());try{const sent=await message.reply({flags:MessageFlags.IsComponentsV2|MessageFlags.SuppressNotifications,components:sentinelComponents(answer,String(message.content??'')),allowedMentions:{repliedUser:false,parse:[],users:[...new Set(answer.userMentionIds??[])],roles:[...new Set(answer.roleMentionIds??[])]}});await rememberConversationReply(sent.id,'sentinel').catch(()=>{});await sentinelRecord({source:'sentinel',category:'audit_query',action:'sentinel.passive_answer',actorId:message.author?.id??null,targetId:message.id,channelId:message.channelId,metadata:{question:String(message.content??'').slice(0,1000),canonicalQuestion:wrapped.canonicalQuestion,language:wrapped.language,matchedEventId:answer.eventId,kind:answer.kind}});}catch(e){console.warn('[sentinel] passive answer failed',e);}
}

export async function sentinelAsk(interaction:ChatInputCommandInteraction,clientArg?:Client){
  const client=clientArg??interaction.client;if(!interaction.inGuild()||interaction.guildId!==guildId)return interaction.reply({content:'This command is available only in the BOM server.',ephemeral:true});
  const perms=interaction.memberPermissions;const configuredRoles=[process.env.DASHBOARD_ADMIN_ROLE_ID??'',...(process.env.SENTINEL_ASK_ROLE_IDS??'').split(',')].map(x=>x.trim()).filter(Boolean);const memberRoles=(interaction.member as any)?.roles?.cache;const roleAllowed=configuredRoles.some(id=>(memberRoles?.has?.(id) ?? (Array.isArray((interaction.member as any)?.roles) && ((interaction.member as any).roles as string[]).includes(id))));if(!perms?.has(PermissionFlagsBits.ManageGuild)&&!perms?.has(PermissionFlagsBits.Administrator)&&!roleAllowed)return interaction.reply({content:'You do not have permission to search Sentinel.',ephemeral:true});
  await interaction.deferReply({flags:MessageFlags.Ephemeral|MessageFlags.IsComponentsV2});const q=interaction.options.getString('question',true).trim();const wrapped=await sentinelConversationAnswer(client,q,interaction.user.id,`sentinel:discord:${interaction.channelId}`);const answer=wrapped.answer;await sentinelRecord({source:'sentinel',category:'audit_query',action:'sentinel.ask',actorId:interaction.user.id,metadata:{question:q,canonicalQuestion:wrapped.canonicalQuestion,language:wrapped.language,matchedEventId:answer.eventId??null,kind:answer.kind}}).catch(()=>{});return interaction.editReply({components:sentinelComponents(answer,q),allowedMentions:{parse:[],users:[...new Set(answer.userMentionIds??[])],roles:[...new Set(answer.roleMentionIds??[])]}});
}
